SELECT e.*
  FROM routine_exceptions e
  JOIN routines r ON r.routine_id = e.routine_id
 WHERE e.routine_exception_id = #{routineExceptionId}
   AND r.user_id = #{userId}
   AND r.is_deleted = 0

SELECT * FROM routine_exceptions
 WHERE routine_id = #{routineId}
 ORDER BY exception_date

