UPDATE routine_exceptions
   SET exception_date   = #{exception.exceptionDate},
       type             = #{exception.type},
       moved_date       = #{exception.movedDate},
       moved_start_time = #{exception.movedStartTime},
       moved_end_time   = #{exception.movedEndTime},
       moved_location   = #{exception.movedLocation},
       note             = #{exception.note}
 WHERE routine_exception_id = #{routineExceptionId}
   AND routine_id = #{exception.routineId}
